// spec: specs/admin-subscriptions.md (раздел 1.3)
// seed: tests/seed.admin.spec.ts
// Расхождения плана с живой страницей (19.11.2026):
//  - поиск по полной строке «QA П3 0012» (и по «0012») возвращает «מוצגים 0 מתוך 0» / «לא נמצאו מנויים»; находит «П3» (и «QA») — ищем по «П3»; возможный баг поиска по нескольким словам, не блокирует тест;
//  - поиск срабатывает по Enter (форма), а не по вводу;
//  - блок «יתרות»: у строк подписи вида «בוסטים · מתוך 2 החודש», «סופר לייק · מתוך 50 החודש + 15 זיכוי», «חזרה אחורה · מתוך 30 החודש», «מתנות חינם»; «הענקת …» — только проверка видимости.
// Только просмотр: «הענקת …», «⋯», «כלי בדיקה» не нажимаются.
import { test, expect } from '@playwright/test';
import path from 'path';

const ADMIN_URL = 'https://magnet-admin.vercel.app';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin-r11.json') });

test.describe('Админка: «מנויים ורכישות» (#01f23b)', () => {
  test('Карточка: подписка, «יתרות», «רכישות (N)», «שולם»/«נכשל» @desktop @prod-safe', async ({ page }) => {
    await page.goto(`${ADMIN_URL}/users`);

    // 1. «מנויים ורכישות» → поиск «QA П3 0012» (по живой странице — «П3») → открыть строку
    await page.getByRole('navigation', { name: 'ניווט ראשי' }).getByRole('link', { name: 'מנויים ורכישות' }).click();
    await expect(page).toHaveURL(/\/subscriptions$/);
    const search = page.getByRole('textbox', { name: 'חיפוש לפי שם, טלפון או מזהה' });
    await search.fill('П3');
    await search.press('Enter');
    await expect(page).toHaveURL(/\/subscriptions\?q=/);
    const userLink = page.getByRole('link', { name: 'מנוי ורכישות של QA П3 0012' });
    await expect(userLink).toBeVisible();
    await userLink.click();
    await expect(page).toHaveURL(/\/subscriptions\/[0-9a-f-]{36}$/);

    // 2. Блоки и таблица «רכישות»
    await expect(page.getByRole('heading', { level: 1, name: 'QA П3 0012' })).toBeVisible();
    const sub = page.getByRole('region', { name: 'מנוי ורכישות' });
    await expect(sub.getByRole('heading', { level: 2, name: 'Magnet Premium' })).toBeVisible();
    await expect(sub.getByText('פעיל', { exact: true })).toBeVisible();
    await expect(sub.getByText('עד החידוש')).toBeVisible();
    for (const label of ['נרכש', 'אמצעי תשלום', 'תשלום אחרון', 'חידוש הבא']) {
      await expect(sub.getByText(label, { exact: true })).toBeVisible();
    }

    // Блок «יתרות»: 4 строки и кнопки «הענקת …» (только видимость, не нажимать)
    await expect(sub.getByRole('heading', { level: 2, name: 'יתרות' })).toBeVisible();
    await expect(sub.getByText(/^בוסטים · /)).toBeVisible();
    await expect(sub.getByText(/^סופר לייק · /)).toBeVisible();
    await expect(sub.getByText(/^חזרה אחורה · /)).toBeVisible();
    await expect(sub.getByText('מתנות חינם', { exact: true })).toBeVisible();
    for (const grant of ['הענקת בוסט', 'הענקת סופר לייק', 'הענקת חזרה אחורה', 'הענקת מתנה']) {
      await expect(sub.getByRole('button', { name: grant })).toBeVisible();
    }

    // «רכישות (N)»: N = числу строк; колонки; номера заказов и суммы; чипы «שולם» и «נכשל»
    const purchasesHeading = sub.getByRole('heading', { level: 2, name: /^רכישות \(\d+\)$/ });
    await expect(purchasesHeading).toBeVisible();
    const n = Number((await purchasesHeading.innerText()).match(/\((\d+)\)/)![1]);
    expect(n).toBeGreaterThan(0);

    const table = sub.getByRole('table').filter({ has: page.getByRole('columnheader', { name: 'הזמנה' }) });
    for (const col of ['הזמנה', 'פריט', 'סכום', 'תשלום', 'סטטוס']) {
      await expect(table.getByRole('columnheader', { name: col, exact: true })).toBeVisible();
    }
    const rows = table.locator('tbody tr');
    await expect(rows).toHaveCount(n);
    for (let i = 0; i < n; i++) {
      const row = rows.nth(i);
      await expect(row.getByRole('cell').nth(0)).toContainText(/P-[0-9A-F]{6}/);
      await expect(row.getByRole('cell').nth(2)).toHaveText(/^₪\d+\.\d\d$/);
    }
    await expect(rows.getByRole('cell', { name: 'שולם', exact: true }).first()).toBeVisible();
    await expect(rows.getByRole('cell', { name: 'נכשל', exact: true }).first()).toBeVisible();
  });
});
